INSERT INTO "Announcement" ("id", "orgId", "authorMembershipId", "title", "body", "pinned", "createdAt", "updatedAt") VALUES
('cmufbz7ij00ksk3kdyjyilaky', 'cmufbz7az000gk3kddl88k8np', 'cmufbz7b60016k3kd5a65fjrt', 'Welcome to OrgOS 🎉', 'We have moved all operations into OrgOS — projects, CRM, HR and finance now live in one connected workspace. Explore the dashboard and let HR know if anything looks off.', 1, 1789464591306, 1790242191307),
('cmufbz7ij00kuk3kdoy5cwgb8', 'cmufbz7az000gk3kddl88k8np', 'cmufbz7b80018k3kdzwnktfcf', 'Q3 All-hands — Friday 4:00 PM', 'Agenda: Q3 results, GreenGrocer go-live plan, hiring pipeline and the new remote policy. Please add questions to the doc before Thursday.', 0, 1789896591307, 1790242191308),
('cmufbz7ik00kwk3kdr60dxj31', 'cmufbz7az000gk3kddl88k8np', 'cmufbz7bd001ck3kd3ybu1sx9', 'New leave policy effective this month', 'Annual leave balance now accrues monthly. Casual leave requests need 48h notice except emergencies. Full policy in Documents → Policies.', 0, 1789637391308, 1790242191308),
('cmufbz7ik00kyk3kd434oyitg', 'cmufbz7az000gk3kddl88k8np', 'cmufbz7b8001ak3kdfugoavd0', 'GreenGrocer milestone 2 signed off ✅', 'Great work team — Core Commerce milestone accepted by client ahead of schedule. Next stop: integrations and migration.', 0, 1790069391308, 1790242191309),
('cmufbz7il00l0k3kdtqfzfqzw', 'cmufbz7az000gk3kddl88k8np', 'cmufbz7bd001ck3kd3ybu1sx9', 'Office closed — Victory Day (16 Dec)', 'The office will remain closed on 16 December. Client communications will resume the next working day.', 0, 1790155791309, 1790242191310);
INSERT INTO "Job" ("id", "orgId", "title", "departmentId", "description", "responsibilities", "requirements", "skills", "experienceLevel", "employmentType", "location", "workMode", "salaryMin", "salaryMax", "currency", "deadline", "openings", "visibility", "status", "hiringManagerMembershipId", "createdAt", "updatedAt") VALUES
('cmufbz7fi00b4k3kdn6fnm2wi', 'cmufbz7az000gk3kddl88k8np', 'Senior Backend Engineer', 'cmufbz7b1000kk3kd98z7wsyc', 'Own critical backend services for client platforms — payments, integrations and data pipelines.', 'Design and evolve service architecture. Mentor mid-level engineers. Own uptime of delivered systems.', 'Node.js/TypeScript, PostgreSQL, Redis, message queues, CI/CD, 5+ years.', 'Communication, Ownership, Craft', 'SENIOR', 'FULL_TIME', 'Dhaka, Bangladesh', 'REMOTE', 12000000, 18000000, 'BDT', 1792834191197, 2, 'PUBLIC', 'OPEN', 'cmufbz7b8001ak3kdfugoavd0', 1790242191198, 1790242191198),
('cmufbz7fj00b6k3kdvmly6qnr', 'cmufbz7az000gk3kddl88k8np', 'Product Designer', 'cmufbz7b2000mk3kdknmk5op5', 'Craft end-to-end product experiences across web and mobile for client projects.', 'Run discovery, wireframe, prototype, hand-off. Contribute to the shared design system.', 'Figma, design systems, portfolio of shipped web products, 3+ years.', 'Communication, Ownership, Craft', 'MID', 'FULL_TIME', 'Dhaka, Bangladesh', 'HYBRID', 8000000, 12000000, 'BDT', 1791970191198, 1, 'PLATFORM', 'OPEN', 'cmufbz7bi001ok3kdq92ox6t3', 1790242191199, 1790242191199),
('cmufbz7fj00b8k3kd617cp2xx', 'cmufbz7az000gk3kddl88k8np', 'Marketing Intern', 'cmufbz7b2000ok3kdrgve23l2', 'Support campaign execution, content calendars and analytics reporting.', 'Draft social copy, assemble reports, coordinate with designers.', 'Final-year student or fresh graduate, strong writing, curiosity for analytics.', 'Communication, Ownership, Craft', 'ENTRY', 'INTERN', 'Dhaka, Bangladesh', 'ONSITE', 1500000, 2000000, 'BDT', 1791278991199, 2, 'PUBLIC', 'OPEN', 'cmufbz7bi001qk3kdz8ebaay1', 1790242191200, 1790242191200),
('cmufbz7fk00bak3kdf1a8gjhz', 'cmufbz7az000gk3kddl88k8np', 'QA Engineer (Contract)', 'cmufbz7b1000kk3kd98z7wsyc', 'Manual + automated QA across active client projects.', 'Write and run test plans, automate regression, report defects.', 'Playwright, API testing, 3+ years agency experience.', 'Communication, Ownership, Craft', 'MID', 'FULL_TIME', 'Dhaka, Bangladesh', 'ONSITE', 6000000, 8000000, 'BDT', 1790242191200, 1, 'PRIVATE', 'PAUSED', 'cmufbz7b8001ak3kdfugoavd0', 1790242191200, 1790242191200);
